base-types.code:
// Define base types first
interface Point {
  x: number;
  y: number;
}

interface DraggableItem {
  id: string;
  position: Point;
  rotation?: number;
  zIndex?: number;
}

interface PolaroidPhoto extends DraggableItem {
  src: string;
  caption: string;
  date: string;
  flipped?: boolean;
  textAngle?: number;
  textX?: number;
  textY?: number;
  dateAngle?: number;
  dateX?: number;
  dateY?: number;
  bgColor?: string;
}

