// Define store structure
interface AppStore {
  polaroidPhotos: PolaroidPhoto[];
  canvasWidth: number;
  canvasHeight: number;
  dragState: DragState | null;
  selectedId: string | null;
}

interface DragState {
  id: string;
  startScreenX: number;
  startScreenY: number;
  currentScreenX: number;
  currentScreenY: number;
  startWorldPos: Point;
  currentWorldPos: Point;
  isDragActive: boolean;
  hasMoved: boolean;
}

