implementation.code:
interface PolaroidPhotoV1 {
  id: string;
  src: string;
  position: Point;
}

interface PolaroidPhotoV2 extends Omit<PolaroidPhotoV1, 'position'> {
  position: Point3D;
  version: 2;
}

type PolaroidPhoto = PolaroidPhotoV1 | PolaroidPhotoV2;

// Type guards for version checking
const isV2Photo = (photo: PolaroidPhoto): photo is PolaroidPhotoV2 => {
  return 'version' in photo && photo.version === 2;
};

// During migration period
interface PolaroidPhoto {
  id: string;
  src: string;
  // Allow both old and new position formats
  position: Point | Point3D;
}

// Helper functions for type narrowing
const isPoint3D = (pos: Point | Point3D): pos is Point3D => {
  return 'z' in pos;
};

const normalizePosition = (pos: Point | Point3D): Point3D => {
  return isPoint3D(pos) ? pos : { ...pos, z: 0 };
};

// Adapters for converting between type versions
const adaptPhotoV1ToV2 = (photoV1: PolaroidPhotoV1): PolaroidPhotoV2 => {
  return {
    ...photoV1,
    position: { ...photoV1.position, z: 0 },
    version: 2 as const
  };
};

const adaptPhotoV2ToV1 = (photoV2: PolaroidPhotoV2): PolaroidPhotoV1 => {
  const { version, position, ...rest } = photoV2;
  return {
    ...rest,
    position: { x: position.x, y: position.y }
  };
};

// types/tests/type-tests.ts
import { PolaroidPhoto, Point, DraggableItem } from '../index';

// Test that PolaroidPhoto extends DraggableItem
const _testExtends: DraggableItem = {} as PolaroidPhoto; // Should compile

// Test that required properties are enforced
const _testRequiredProps: PolaroidPhoto = {
  id: "test",
  src: "test.jpg",
  position: { x: 0, y: 0 },
  caption: "test",
  date: "2025-01-01"
}; // Should compile

// Test that invalid assignments fail
// @ts-expect-error - Missing required properties
const _testInvalid: PolaroidPhoto = {
  id: "test"
}; // Should NOT compile

// Test generic constraints
function testGeneric<T extends DraggableItem>(item: T): T {
  item.position.x = 100; // Should compile
  return item;
}

const result = testGeneric({} as PolaroidPhoto); // Should compile
// @ts-expect-error - String doesn't extend DraggableItem
const invalid = testGeneric("string"); // Should NOT compile

import { z } from 'zod';

// Define Zod schemas that match TypeScript interfaces
const PointSchema = z.object({
  x: z.number(),
  y: z.number()
});

const PolaroidPhotoSchema = z.object({
  id: z.string(),
  src: z.string(),
  position: PointSchema,
  caption: z.string(),
  date: z.string(),
  rotation: z.number().optional(),
  zIndex: z.number().optional(),
  flipped: z.boolean().optional()
});

// Type-safe parsing with runtime validation
const parsePolaroidPhoto = (data: unknown): PolaroidPhoto => {
  return PolaroidPhotoSchema.parse(data);
};

// Use at API boundaries
const loadPhotosFromAPI = async (): Promise<PolaroidPhoto[]> => {
  const response = await fetch('/api/photos');
  const data = await response.json();

  if (!Array.isArray(data)) {
    throw new Error('Expected array of photos');
  }

  return data.map(parsePolaroidPhoto);
};

