implementation.code:
interface ReadonlyPolaroidPhoto {
  readonly id: string;
  readonly src: string;
  readonly caption: string;
  readonly date: string;
  position: Point; // Mutable through store updates
}

type PolaroidId = string & { __brand: 'PolaroidId' };
type UserId = string & { __brand: 'UserId' };

const createPolaroidId = (id: string): PolaroidId => id as PolaroidId;
const createUserId = (id: string): UserId => id as UserId;

interface PolaroidPhoto {
  id: PolaroidId; // Cannot accidentally use UserId
  src: string;
  position: Point;
}

type Theme = 'light' | 'dark' | 'auto';

const getThemeColor = (theme: Theme): string => {
  switch (theme) {
    case 'light':
      return '#ffffff';
    case 'dark':
      return '#000000';
    case 'auto':
      return '#f0f0f0';
    default:
      // TypeScript will error if we add new theme without handling it
      const exhaustiveCheck: never = theme;
      throw new Error(`Unhandled theme: ${exhaustiveCheck}`);
  }
};
